(() => {
 'use strict';
 const D=window.AE48_DATA,C=window.AE48RequestCore,dialog=document.getElementById('detail'),content=document.getElementById('dialog-content');
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const money=n=>new Intl.NumberFormat('vi-VN').format(n)+' ₫';
 let chosen=[],extra=[],sending=false,kind='';
 const ready=name=>location.protocol==='https:'&&!!document.querySelector(`form[data-schema="${name}"] input[name="form-name"]`)&&!document.querySelector(`form[data-schema="${name}"]`).hasAttribute('data-netlify');
 const listId='request-member-names';
 const peopleOptions=()=>`<datalist id="${listId}">${D.members.map(m=>`<option value="${esc(m.name)}"></option>`).join('')}</datalist>`;
 const heading=(title,subtitle)=>`<div class="dialog-head"><div><h2 id="dialog-title">${title}</h2><p>${subtitle}</p></div><button class="close" data-action="close" aria-label="Đóng biểu mẫu">×</button></div>`;
 const field=(label,body)=>`<label class="form-field"><span>${label}</span>${body}</label>`;
 const sender=()=>field('Tên người gửi <span class="required">*</span>',`<input name="sender_name" list="${listId}" required maxlength="80" autocomplete="name" placeholder="Chọn hoặc nhập tên của bạn">`);
 const footer=name=>`<div class="form-disclaimer">Yêu cầu gửi riêng cho admin. Chỉ sau khi admin duyệt và cập nhật dữ liệu, công nợ mới thay đổi.</div>${!ready(name)?'<p class="form-local" role="note">Bản xem này chưa kết nối nơi nhận yêu cầu. Bạn có thể thử điền; chưa thể gửi đến admin.</p>':''}<p id="request-error" class="form-error" role="alert"></p><button class="button primary request-submit" type="submit" ${ready(name)?'':'disabled'}>${name==='ae48-bills'?'Gửi bill chờ duyệt':'Gửi góp ý cho admin'}</button>`;
 const hidden=name=>`<input type="hidden" name="form-name" value="${name}"><input type="hidden" name="request_id"><input type="hidden" name="submitted_at"><input type="hidden" name="snapshot_at" value="${esc(D.updatedAt)}"><label class="honeypot" hidden aria-hidden="true">Không điền ô này<input name="bot-field" tabindex="-1" autocomplete="off"></label>`;
 const today=()=>new Intl.DateTimeFormat('en-CA',{year:'numeric',month:'2-digit',day:'2-digit',timeZone:D.timezone}).format(new Date());
 function open(html){content.innerHTML=html;if(!dialog.open)dialog.showModal();dialog.scrollTop=0;dialog.querySelector('.close')?.focus();}
 function bill(sessionId){
  kind='bill';extra=[];const session=D.sessions.find(s=>s.id===sessionId);chosen=session?[...session.participants]:[];
  open(heading('Gửi bill mới','Cầu lông hay nhậu, chia đều và chờ admin duyệt.')+`<form id="request-form" name="ae48-bills" method="POST" action="/" enctype="multipart/form-data">${hidden('ae48-bills')}${peopleOptions()}<div class="form-grid">${sender()}${field('Người đã ứng tiền <span class="required">*</span>',`<input name="payer_name" list="${listId}" required maxlength="80" placeholder="Ai đã trả khoản này?">`)}</div><div class="form-grid">${field('Hoạt động',`<select name="category" id="bill-category"><option value="sport" ${session?.category==='sport'?'selected':''}>Cầu lông</option><option value="food" ${session?.category==='food'?'selected':''}>Nhậu / ăn uống</option></select>`)}${field('Ngày chi <span class="required">*</span>',`<input type="date" name="expense_date" value="${session?.date||today()}" required>`)}</div>${field('Buổi phát sinh',`<select name="session_id" id="bill-session"></select>`)}<div id="new-session-field">${field('Tên / mô tả buổi mới <span class="required">*</span>','<input name="new_session_title" maxlength="160" placeholder="Ví dụ: The B tối thứ 5">')}</div>${field('Nội dung khoản chi <span class="required">*</span>','<input name="description" required maxlength="200" placeholder="Tiền sân, ống cầu, nước hoặc hóa đơn nhậu…">')}${field('Số tiền · VND <span class="required">*</span>','<input type="number" name="amount" id="bill-amount" required min="1" max="1000000000" step="1" inputmode="numeric" placeholder="Ví dụ: 340000">')}<section class="form-field"><div class="participants-head"><span>Người chịu tiền <span class="required">*</span></span><span id="participant-count" class="muted"></span></div><p class="form-help">Danh sách đề xuất; admin kiểm tra lại trước khi duyệt.</p><div id="participant-choices" class="participant-choices"></div><div class="add-person"><input id="new-participant" aria-label="Tên thành viên hoặc khách mới" maxlength="80" placeholder="Thêm thành viên hoặc khách mới"><button type="button" class="button" data-request="add-person">Thêm</button></div><div id="split-preview" class="split-preview" aria-live="polite"></div><input type="hidden" name="participants"><input type="hidden" name="allocation_preview"></section>${field('Ảnh / file hóa đơn <span class="optional">Không bắt buộc</span>','<input type="file" name="receipt" accept="image/jpeg,image/png,image/webp,application/pdf,.jpg,.jpeg,.png,.webp,.pdf"><small class="form-help">JPG, PNG, WebP hoặc PDF · tối đa 5 MB</small>')}${field('Ghi chú thêm <span class="optional">Không bắt buộc</span>','<textarea name="note" rows="2" maxlength="1500" placeholder="Thông tin admin cần biết…"></textarea>')}${footer('ae48-bills')}</form>`);
  updateSessionOptions(session?.id);paintParticipants();updatePreview();
 }
 function updateSessionOptions(id){const form=document.getElementById('request-form');const category=form.elements.category.value;const select=document.getElementById('bill-session');select.innerHTML='<option value="new">Buổi mới / chưa có trong danh sách</option>'+D.sessions.filter(s=>s.category===category).map(s=>`<option value="${s.id}" ${s.id===id?'selected':''}>${s.id} · ${esc(s.title)}</option>`).join('');updateNewSession();}
 function updateNewSession(){const fresh=document.getElementById('bill-session').value==='new';const section=document.getElementById('new-session-field');section.hidden=!fresh;const input=section.querySelector('input');input.required=fresh;input.disabled=!fresh;}
 function paintParticipants(){const all=[...D.members.map(m=>m.name),...extra];document.getElementById('participant-choices').innerHTML=all.map((name,i)=>`<label class="participant-option"><input type="checkbox" value="${esc(name)}" data-participant ${chosen.includes(name)?'checked':''}><span>${esc(name)}</span>${i>=D.members.length?'<small>Mới</small>':''}</label>`).join('');document.getElementById('participant-count').textContent=chosen.length+' người';}
 function updatePreview(){const form=document.getElementById('request-form');if(!form||kind!=='bill')return;form.elements.participants.value=JSON.stringify(chosen);const target=document.getElementById('split-preview');document.getElementById('participant-count').textContent=chosen.length+' người';const amount=form.elements.amount.valueAsNumber;let allocation=[];try{allocation=C.split(amount,chosen);target.innerHTML=`<div class="split-heading"><strong>Chia đều dự kiến</strong><span>${chosen.length} người · ${money(amount)}</span></div>${allocation.map(p=>`<div class="split-line"><span>${esc(p.name)}</span><strong class="money">${money(p.amount)}</strong></div>`).join('')}`;}catch{target.innerHTML='<p class="form-help">Nhập số tiền và chọn người để xem phần chia.</p>';}form.elements.allocation_preview.value=allocation.map(p=>p.name+': '+p.amount+' VND').join('\n');}
 function addPerson(){const input=document.getElementById('new-participant');const name=input.value.trim();if(!name)return;const all=[...D.members.map(m=>m.name),...extra];const existing=all.find(n=>C.normalize(n)===C.normalize(name));if(existing){if(!chosen.includes(existing))chosen.push(existing);}else{extra.push(name);chosen.push(name);}input.value='';paintParticipants();updatePreview();}
 function feedback(sessionId){
  kind='comment';const session=D.sessions.find(s=>s.id===sessionId);if(!session)return;
  open(heading('Góp ý khoản chi',esc(session.id+' · '+session.title))+`<form id="request-form" name="ae48-comments" method="POST" action="/">${hidden('ae48-comments')}${peopleOptions()}<input type="hidden" name="session_id" value="${session.id}"><input type="hidden" name="session_title" value="${esc(session.title)}">${sender()}${field('Khoản cần kiểm tra',`<select name="expense_target"><option value="${session.id}:all">Toàn bộ buổi / danh sách chia tiền</option>${session.costs.map((c,i)=>`<option value="${session.id}:${i}:${esc(c.label)}">${esc(c.label)} · ${money(c.amount)} · ${esc(c.payer||'Chưa rõ người ứng')}</option>`).join('')}</select>`)}${field('Vấn đề bạn thấy',`<select name="reason"><option>Số tiền chưa hợp lý</option><option>Danh sách người chịu tiền chưa đúng</option><option>Có thể trùng khoản chi</option><option>Người ứng tiền chưa đúng</option><option>Vấn đề khác</option></select>`)}${field('Nội dung góp ý <span class="required">*</span>','<textarea name="comment" required minlength="5" maxlength="2000" rows="5" placeholder="Ví dụ: Hôm đó tôi không tham gia, nhờ admin kiểm tra lại danh sách chia tiền."></textarea>')}${footer('ae48-comments')}</form>`);
 }
 function error(message){const el=document.getElementById('request-error');if(el)el.textContent=message;}
 document.addEventListener('click',e=>{const button=e.target.closest('button');if(!button)return;if(sending&&(button.dataset.action==='close'||button.hasAttribute('data-submit-bill')||button.dataset.feedbackSession)){e.preventDefault();e.stopImmediatePropagation();return;}if(button.hasAttribute('data-submit-bill'))bill(button.dataset.submitBill);if(button.dataset.feedbackSession)feedback(button.dataset.feedbackSession);if(button.dataset.request==='add-person')addPerson();},true);
 document.addEventListener('keydown',e=>{if(e.target.id==='new-participant'&&e.key==='Enter'){e.preventDefault();addPerson();}});
 document.addEventListener('change',e=>{if(kind==='bill'&&e.target.id==='bill-category'){chosen=[];updateSessionOptions();paintParticipants();updatePreview();}if(kind==='bill'&&e.target.id==='bill-session'){const s=D.sessions.find(s=>s.id===e.target.value);chosen=s?[...s.participants]:[];if(s?.date)document.getElementById('request-form').elements.expense_date.value=s.date;updateNewSession();paintParticipants();updatePreview();}if(e.target.hasAttribute('data-participant')){const names=[...D.members.map(m=>m.name),...extra];chosen=names.filter(n=>[...document.querySelectorAll('[data-participant]:checked')].some(c=>c.value===n));updatePreview();}if(e.target.name==='receipt')error(C.fileError(e.target.files?.[0]));});
 document.addEventListener('input',e=>{if(e.target.id==='bill-amount')updatePreview();});
 dialog.addEventListener('cancel',e=>{if(sending)e.preventDefault();});
 document.addEventListener('submit',async e=>{
  if(e.target.id!=='request-form')return;e.preventDefault();const form=e.target;if(sending)return;error('');if(!form.reportValidity())return;
  const name=form.elements['form-name'].value;if(!ready(name)){error('Bản xem này chưa kết nối nơi nhận yêu cầu. Chưa có thông tin nào được gửi.');return;}
  try{
   if(kind==='bill'){C.split(form.elements.amount.valueAsNumber,chosen);updatePreview();const file=form.elements.receipt.files?.[0],problem=C.fileError(file);if(problem)throw new Error(problem);}
   if(!form.elements.sender_name.value.trim())throw new Error('Vui lòng nhập tên người gửi.');
   if(kind==='bill'&&(!form.elements.payer_name.value.trim()||!form.elements.description.value.trim()||form.elements.session_id.value==='new'&&!form.elements.new_session_title.value.trim()))throw new Error('Vui lòng điền đủ tên người ứng, nội dung khoản chi và tên buổi.');
   if(kind==='comment'&&form.elements.comment.value.trim().length<5)throw new Error('Góp ý cần ít nhất 5 ký tự có nội dung.');
   if(!form.elements.request_id.value)form.elements.request_id.value=crypto.randomUUID();form.elements.submitted_at.value=new Date().toISOString();const data=new FormData(form);const amount=form.elements.amount;if(amount)data.set('amount',String(amount.valueAsNumber));
   const submit=form.querySelector('[type="submit"]');sending=true;submit.disabled=true;submit.textContent='Đang gửi…';form.setAttribute('aria-busy','true');const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),45000);
   let response;try{response=await fetch('/',{method:'POST',body:kind==='bill'?data:new URLSearchParams(data),signal:controller.signal,...(kind==='comment'?{headers:{'Content-Type':'application/x-www-form-urlencoded'}}:{})});}finally{clearTimeout(timeout);}
   if(!response.ok)throw new Error('Nơi nhận chưa xác nhận yêu cầu. Vui lòng thử lại hoặc liên hệ admin.');
   const requestId=form.elements.request_id.value;open(heading('Đã gửi tới admin','Cảm ơn bạn đã giúp nhóm đối chiếu rõ ràng hơn.')+`<div class="request-success"><span class="badge credit">Chờ admin duyệt</span><p>${kind==='bill'?'Bill và danh sách đề xuất đã được gửi.':'Góp ý đã được gửi riêng cho admin.'} Công nợ hiện tại chưa thay đổi.</p><small>Mã yêu cầu: ${esc(requestId)}</small><button class="button primary" data-action="close">Về sổ quỹ</button></div>`);
  }catch(err){error(err.name==='AbortError'?'Chưa nhận được xác nhận gửi. Kiểm tra với admin trước khi gửi lại để tránh trùng.':err.message);}finally{sending=false;if(form.isConnected){form.removeAttribute('aria-busy');const submit=form.querySelector('[type="submit"]');submit.disabled=!ready(name);submit.textContent=kind==='bill'?'Gửi bill chờ duyệt':'Gửi góp ý cho admin';}}
 });
})();
